    /**
     * Layer position on Z axis
     */
    zIndex?: number;
    /**
     * Whether HTML element should follow camera position
     */
    transformByCameraPosition?: boolean;
}

export interface GraphPortalProps {
    /**
     * Additional CSS classes for layer
     */
    className?: string;
    /**
     * Layer position on Z axis
     */
    zIndex?: number;
    /**
     * Whether HTML element should follow camera position
     * @default false
     */
