export type GraphProps = Pick<Partial<TBlockListProps>, "renderBlock"> & Partial<TGraphEventCallbacks> & {
    className?: string;
    blockListClassName?: string;
    graph: Graph;
    reactLayerRef?: React.MutableRefObject<ReactLayer | null>;
    children?: React.ReactNode;
};

export type HookGraphParams = Pick<TGraphConfig, "settings" | "layers"> & {
    graph?: Graph;
    name?: string;
    viewConfiguration?: {
        colors?: RecursivePartial<TGraphColors>;
        constants?: RecursivePartial<TGraphConstants>;
    };
};

export type TGraphBlockProps<T extends TBlock> = {
    /**
     * Graph instance
     */
    graph: Graph;
    /**
     * Block instance
     */
    block: T;
    /**
     * Class name for wrapper div
     * * The difference between the "containerClassName" and "className" props:
     * - containerClassName is applied to the container div
     * - className is applied to the wrapper div
     * ```jsx
     * // container for position and size
     * <div className={`graph-block-container ${containerClassName}`}>
     *   // wrapper for block content
     *   <div className={`graph-block-wrapper ${className}`}>
     *     {children}
     *   </div>
     * </div>
     * ```
     */
    className?: string;
    /**
     * Class name for container div
     * * The difference between the "containerClassName" and "className" props:
     * - containerClassName is applied to the container div
     * - className is applied to the wrapper div
     * ```jsx
     * // container for position and size
     * <div className={`graph-block-container ${containerClassName}`}>
     *   // wrapper for block content
     *   <div className={`graph-block-wrapper ${className}`}>
     *     {children}
     *   </div>
     * </div>
     * ```
     */
    containerClassName?: string;
    /**
     * Flag to hide canvas block automatically when react will render the block.
     * If you want to manage canvas block visibility manually, you can set `autoHideCanvas` to `false`, and pass `canvasVisible` prop to control it.
     */
    autoHideCanvas?: boolean;
    /**
     * Flag to manage visibility of canvas block.
     * If you want to manage visibility of canvas block manually, you can set `autoHideCanvas` to `false`, and pass `canvasVisible` prop to control it.
     */
    canvasVisible?: boolean;
    children: React.ReactNode;
};

export type TGraphEventCallbacks = {
    click: (data: UnwrapGraphEventsDetail<"click">, event: UnwrapGraphEvents<"click">) => void;
    dblclick: (data: UnwrapGraphEventsDetail<"dblclick">, event: UnwrapGraphEvents<"dblclick">) => void;
    onCameraChange: (data: UnwrapGraphEventsDetail<"camera-change">, event: UnwrapGraphEvents<"camera-change">) => void;
    onBlockDragStart: (data: UnwrapGraphEventsDetail<"block-drag-start">, event: UnwrapGraphEvents<"block-drag-start">) => void;
    onBlockDrag: (data: UnwrapGraphEventsDetail<"block-drag">, event: UnwrapGraphEvents<"block-drag">) => void;
    onBlockDragEnd: (data: UnwrapGraphEventsDetail<"block-drag-end">, event: UnwrapGraphEvents<"block-drag-end">) => void;
    onBlockSelectionChange: (data: UnwrapGraphEventsDetail<"blocks-selection-change">, event: UnwrapGraphEvents<"blocks-selection-change">) => void;
    onBlockAnchorSelectionChange: (data: UnwrapGraphEventsDetail<"block-anchor-selection-change">, event: UnwrapGraphEvents<"block-anchor-selection-change">) => void;
    onBlockChange: (data: UnwrapGraphEventsDetail<"block-change">, event: UnwrapGraphEvents<"block-change">) => void;
    onBlocksGeometryChange: (data: UnwrapGraphEventsDetail<"blocks-geometry-change">, event: UnwrapGraphEvents<"blocks-geometry-change">) => void;
    onConnectionSelectionChange: (data: UnwrapGraphEventsDetail<"connection-selection-change">, event: UnwrapGraphEvents<"connection-selection-change">) => void;
    onStateChanged: (data: UnwrapGraphEventsDetail<"state-change">, event: UnwrapGraphEvents<"state-change">) => void;
};

